	}
	command.Shard = args[i+1]
	i++
case "--run":
	if i+1 >= len(args) || strings.HasPrefix(args[i+1], "-") {
		return command, errors.New("--run requires a durable run ID")
	}
	command.RunID = args[i+1]
	i++
