			return "Used " + name + ": " + detail
		}
		if name != "" {
			return "Used " + name
		}
		return "Used a tool"
	case "lifecycle":
		if action != "" {
			return "Agent is " + strings.ReplaceAll(action, "_", " ")
		}
		return "Agent status changed"

